def parse_positive_float(raw: str) -> float:
    try:
        value = float(raw)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("timeout은 숫자여야 합니다") from exc
    if value <= 0:
        raise argparse.ArgumentTypeError("timeout은 0보다 커야 합니다")
    return value
